text:
{
  "components": [
    {
      "type": "claim",
      "quote": "the SFOE prepares a draft version of the detailed plan and initiates the consultation and participation procedure in the cantons",
      "gist": "SFOE drafts a detailed plan and starts canton consultation"
    },
    {
      "type": "claim",
      "quote": "the SFOE finalises the detailed plan and initiates a consultation of public authorities",
      "gist": "SFOE finalises plan and consults public authorities"
    },
    {
      "type": "condition",
      "quote": "Within two months after the conclusion of the consultation of public authorities",
      "gist": "Two months after public authority consultation ends"
    },
    {
      "type": "obligation",
      "quote": "the SFOE petitions the Federal Council to designate the planning corridor and applicable transmission technology",
      "gist": "SFOE must petition Federal Council to designate corridor and tech"
    },
    {
      "type": "claim",
      "quote": "The procedure culminates in a detailed plan in which the Federal Council defines a corridor for the transmission line project and specifies the type of transmission technology to be used (overhead lines or underground cables)",
      "gist": "Final plan includes Federal Council's defined corridor and transmission tech choice"
    }
  ]
}
